<script setup lang="ts">
import {computed,ref} from 'vue'
import {useResource,useTask,confirmAction} from '../composables/useData'
import {service} from '../services'
import {useAuth} from '../stores/auth'
import type {Department} from '../types/domain'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import Icon from '../components/Icon.vue'
const auth=useAuth()
const departments=useResource('departments'),users=useResource('users'),task=useTask(),selected=ref('d1'),dialog=ref(false),draft=ref<Partial<Department>>({})
function branch(parentId=''):any[]{return departments.items.value.filter(d=>d.parentId===parentId).sort((a,b)=>a.sort-b.sort).map(d=>({...d,label:d.name,children:branch(d.id)}))}
const tree=computed(()=>branch()),current=computed(()=>departments.items.value.find(d=>d.id===selected.value)||departments.items.value[0]),members=computed(()=>users.items.value.filter(u=>u.departmentId===current.value?.id))
function edit(department?:Department){draft.value=department?structuredClone(department):{name:'',parentId:current.value?.id||'',leaderId:'',sort:0};dialog.value=true}
async function save(){await task.run(async()=>{const d=await service.save('departments',draft.value);selected.value=d.id;dialog.value=false;await departments.load()})}
async function remove(d:Department){if(!await confirmAction(`删除「${d.name}」？有成员、下级或知识授权的部门不能删除。`))return;await task.run(async()=>{await service.remove('departments',[d.id]);await departments.load();selected.value=departments.items.value[0]?.id||''},'部门已删除')}
</script>
<template><PageHeader title="部门管理" description="维护团队组织结构、部门负责人和成员归属。"><button class="btn primary" @click="edit()"><Icon name="plus"/>新增部门</button></PageHeader><LoadState :loading="departments.loading.value" :error="departments.error.value||users.error.value" @retry="departments.load();users.load()"><div class="tree-layout"><aside class="panel tree-panel"><div class="tree-title"><h2>组织结构</h2><span class="small faint">{{departments.items.value.length}} 个部门</span></div><el-tree :data="tree" node-key="id" default-expand-all highlight-current :current-node-key="current?.id" @node-click="(node:any)=>selected=node.id" aria-label="部门结构树" /></aside><section v-if="current" class="panel"><div class="panel-head"><h2>{{current.name}}</h2><div class="row-actions"><button class="text-button" @click="edit(current)">编辑部门</button><button class="text-button danger" @click="remove(current)">删除</button></div></div><p class="small muted">负责人：{{users.items.value.find(u=>u.id===current?.leaderId)?.displayName||'未设置'}} · 直属成员 {{members.length}} 人</p><div class="table-wrap" style="padding:0;margin-top:20px"><table class="data-table" style="min-width:360px"><thead><tr><th>姓名</th><th>用户名</th><th>状态</th></tr></thead><tbody><tr v-for="u in members" :key="u.id"><td>{{u.displayName}}</td><td>{{u.username}}</td><td>{{u.status==='active'?'启用':'停用'}}</td></tr></tbody></table><div v-if="!members.length" class="empty-inline">暂无直属成员，请在用户管理中分配。</div></div><RouterLink v-if="auth.has('org.users.manage')" to="/org/users" class="text-button" style="display:inline-block;margin-top:16px">前往用户管理 →</RouterLink></section></div></LoadState><el-dialog v-model="dialog" :title="draft.id?'编辑部门':'新增部门'" width="480px"><form id="department-form" @submit.prevent="save"><label class="field">部门名称<input v-model="draft.name" required maxlength="50"></label><label class="field">上级部门<el-select v-model="draft.parentId" aria-label="上级部门"><el-option label="无（顶级部门）" value=""/><el-option v-for="d in departments.items.value.filter(d=>d.id!==draft.id)" :key="d.id" :label="d.name" :value="d.id"/></el-select></label><label class="field">部门负责人<el-select v-model="draft.leaderId" clearable aria-label="部门负责人"><el-option label="暂不设置" value=""/><el-option v-for="u in users.items.value.filter(u=>u.departmentId===draft.id&&u.status==='active')" :key="u.id" :label="u.displayName" :value="u.id"/></el-select></label><label class="field">排序<input v-model.number="draft.sort" type="number" min="0" max="999"></label><p v-if="task.error.value" class="field-error">{{task.error.value}}</p></form><template #footer><button class="btn quiet" @click="dialog=false">取消</button><button class="btn primary" form="department-form" :disabled="task.busy.value">保存部门</button></template></el-dialog></template>
